@custom-variant dark (&:where(.dark, .dark *));

@theme {
  --color-knx-obsidian: #090B0E;
  --color-knx-slate: #11161D;
  --color-knx-tyvek: #F1F5F9;
  --color-knx-primary: #F8FAFC;
  --color-knx-muted: #94A3B8;
  --color-knx-cyan: #00F0FF;
  --color-knx-magenta: #FF007F;
  --color-knx-amber: #FF7A00;
  --color-knx-volt: #D4FF00;

  --font-display: var(--font-oswald), sans-serif;
  --font-body: var(--font-manrope), -apple-system, BlinkMacSystemFont, sans-serif;
  --font-mono-tech: var(--font-jetbrains), monospace;

  --ease-out: cubic-bezier(0.23, 1, 0.32, 1);
  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out: cubic-bezier(0.77, 0, 0.175, 1);
  --dur-fast: 180ms;
  --dur-base: 420ms;
  --dur-slow: 800ms;
}

:root {
  --bg-obsidian: #090B0E;
  --bg-slate: #11161D;
  --bg-panel: rgba(17, 22, 29, 0.82);
  --tyvek-white: #F1F5F9;
  --text-primary: #F8FAFC;
  --text-muted: #94A3B8;
  --border-hairline: rgba(226, 232, 240, 0.14);

  /* Cyberpunk Lighting & UI Accents */
  --neon-cyan: #00F0FF;
  --neon-magenta: #FF007F;
  --hazard-amber: #FF7A00;
  --acid-volt: #D4FF00;
}

/* Let the telemetry text shrink before applying its existing ellipsis. */
.synapxe-root [data-testid="fabric-weather-control-bar"] > div > div {
  min-width: 0;
  max-width: 100%;
}

@media (max-width: 639px) {
  /* Keep every header action available without compressing the wordmark. */
  .synapxe-root > header > div {
    height: auto;
    flex-wrap: wrap;
    padding-block: 12px;
  }

  .synapxe-root > header > div > div:last-child {
    width: 100%;
    flex-wrap: wrap;
    justify-content: space-between;
  }
}

.chamfer-btn {
  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 12px 100%, 0 calc(100% - 12px));
}

.chamfer-sm {
  clip-path: polygon(0 0, calc(100% - 8px) 0, 100% 8px, 100% 100%, 8px 100%, 0 calc(100% - 8px));
}

.chamfer-card {
  clip-path: polygon(0 0, calc(100% - 14px) 0, 100% 14px, 100% 100%, 14px 100%, 0 calc(100% - 14px));
}

/* Optical Shader Modes for Hero */
.shader-optical {
  filter: contrast(1.06) saturate(1.12);
}

.shader-thermal {
  filter: contrast(1.35) saturate(1.6);
}

.shader-uv-lumen {
  filter: contrast(1.45) brightness(0.95) saturate(1.8);
}

/* Colorway Swatch Image Filters */
.swatch-stealth-black {
  filter: contrast(1.04) brightness(0.98) saturate(0.95);
}

.swatch-oxide-slate {
  filter: sepia(0.22) hue-rotate(155deg) saturate(1.35) contrast(1.08) brightness(1.05);
}

.swatch-neon-noir {
  filter: hue-rotate(275deg) saturate(1.85) contrast(1.18) brightness(1.04);
}

/* The interface powers on like an LED sign, then settles into its steady state. */
@media (prefers-reduced-motion: no-preference) {
  .synapxe-root [data-sx-reveal][data-sx-state] {
    transition: border-color 300ms cubic-bezier(0.22, 1, 0.36, 1);
  }

  .synapxe-root [data-sx-state="pending"]:not(:focus-within) {
    opacity: 0;
  }
  .synapxe-root [data-sx-activated="true"] {
    animation: sx-power-on 620ms steps(1, end) var(--sx-delay, 0ms) both;
  }
  .synapxe-root [data-sx-reveal]:focus-within {
    opacity: 1;
    transform: none;
    transition: none;
    animation: none;
  }

  .synapxe-root [data-sx-reveal="heading"] {
    position: relative;
  }
  .synapxe-root [data-sx-reveal="heading"]::after {
    content: "";
    position: absolute;
    bottom: 0;
    left: 0;
    width: 72px;
    height: 1px;
    background: currentColor;
    color: var(--neon-cyan);
    transform-origin: left;
    transition: transform 800ms cubic-bezier(0.22, 1, 0.36, 1) 100ms;
    pointer-events: none;
  }
  .synapxe-root [data-sx-reveal="heading"][data-sx-state="pending"]::after {
    transform: scaleX(0);
  }

  .synapxe-root .sx-product:nth-child(4n + 2) { --sx-delay: 70ms; }
  .synapxe-root .sx-product:nth-child(4n + 3) { --sx-delay: 140ms; }
  .synapxe-root .sx-product:nth-child(4n + 4) { --sx-delay: 210ms; }

  .sx-hero-load {
    animation: sx-power-on 620ms steps(1, end) both;
  }
  .sx-hero-sign { animation: sx-sign-on 680ms steps(1, end) both; }
  .sx-hero-load--eyebrow { animation-delay: 80ms; }
  .sx-hero-load--copy { animation-delay: 160ms; }
  .sx-hero-load--actions { animation-delay: 240ms; }
  .sx-hero-load--hud { animation-delay: 320ms; }
  .sx-hero-load:focus-within { animation: none; }
}

@keyframes sx-power-on {
  0% { opacity: 0; }
  12% { opacity: 0.85; }
  22% { opacity: 0.12; }
  36% { opacity: 1; }
  45% { opacity: 0.25; }
  59% { opacity: 1; }
  66% { opacity: 0.65; }
  75%, 100% { opacity: 1; }
}
@keyframes sx-sign-on {
  0%, 22% { opacity: 0.7; }
  12%, 36%, 59%, 75%, 100% { opacity: 1; }
  45% { opacity: 0.45; }
  66% { opacity: 0.8; }
}

@media (prefers-reduced-motion: no-preference) and (max-width: 1279px) {
  .synapxe-root .sx-product:nth-child(n) { --sx-delay: 0ms; }
  .synapxe-root .sx-product:nth-child(3n + 2) { --sx-delay: 70ms; }
  .synapxe-root .sx-product:nth-child(3n + 3) { --sx-delay: 140ms; }
}
@media (prefers-reduced-motion: no-preference) and (max-width: 1023px) {
  .synapxe-root .sx-product:nth-child(n) { --sx-delay: 0ms; }
  .synapxe-root .sx-product:nth-child(2n) { --sx-delay: 70ms; }
}
@media (prefers-reduced-motion: no-preference) and (max-width: 639px) {
  .synapxe-root .sx-product:nth-child(n) { --sx-delay: 0ms; }
}

@media (prefers-reduced-motion: no-preference) {
  .synapxe-root :is(button, a, select, input[type="range"]) {
    transition: color 220ms cubic-bezier(0.22, 1, 0.36, 1),
      background-color 220ms cubic-bezier(0.22, 1, 0.36, 1),
      border-color 220ms cubic-bezier(0.22, 1, 0.36, 1),
      filter 220ms cubic-bezier(0.22, 1, 0.36, 1),
      scale 180ms cubic-bezier(0.22, 1, 0.36, 1);
  }
  .synapxe-root :is(button, a):active { scale: 0.97; }
  .sx-cart-enter { animation: sx-panel-enter 400ms cubic-bezier(0.22, 1, 0.36, 1) both; }
  .sx-disclosure-enter { animation: sx-power-on 350ms steps(1, end) both; }
}
@media (hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference) {
  .synapxe-root :is(button, a, select):hover { filter: brightness(1.18); }
}
@keyframes sx-panel-enter {
  from { opacity: 0.6; transform: translateX(16px); }
  to { opacity: 1; transform: translateX(0); }
}

@media (prefers-reduced-motion: reduce) {
  .synapxe-root .sx-product img { transition: none; }
  .synapxe-root .sx-product:hover img { transform: none; }
}

/* Custom Range Input for Fabric Lab & Biometric Sliders */
input[type="range"].synapxe-slider {
  -webkit-appearance: none;
  appearance: none;
  background: rgba(226, 232, 240, 0.14);
  height: 6px;
  outline: none;
}

input[type="range"].synapxe-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 18px;
  height: 18px;
  background: #00F0FF;
  border: 2px solid #090B0E;
  cursor: pointer;
  clip-path: polygon(0 0, calc(100% - 4px) 0, 100% 4px, 100% 100%, 4px 100%, 0 calc(100% - 4px));
  box-shadow: 0 0 12px rgba(0, 240, 255, 0.65);
}

input[type="range"].synapxe-slider::-moz-range-thumb {
  width: 18px;
  height: 18px;
  background: #00F0FF;
  border: 2px solid #090B0E;
  cursor: pointer;
  border-radius: 0;
  box-shadow: 0 0 12px rgba(0, 240, 255, 0.65);
}

/* Tyvek paper noise subtle pattern */
.tyvek-surface {
  background-color: #F1F5F9;
  background-image: 
    linear-gradient(135deg, rgba(15, 23, 42, 0.03) 25%, transparent 25%),
    linear-gradient(225deg, rgba(15, 23, 42, 0.03) 25%, transparent 25%),
    linear-gradient(45deg, rgba(15, 23, 42, 0.02) 25%, transparent 25%),
    linear-gradient(315deg, rgba(15, 23, 42, 0.03) 25%, #F1F5F9 25%);
  background-size: 24px 24px;
}

/* Scenic closing frame: the image stays still while rain passes over it. */
.scenic-footer-image {
  background: linear-gradient(180deg, rgba(9, 11, 14, .8), rgba(9, 11, 14, .18) 48%, rgba(9, 11, 14, .88)), url('/templates/synapxe/footer-scene.webp') center / cover no-repeat;
}

